args.command:
$results = @()
Get-ChildItem -Path servisler -Recurse -Filter *.ini | Where-Object { $_.FullName -notlike '*\yedek\*' } | ForEach-Object {
    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
    $encoding = [System.Text.Encoding]::UTF8
    $hasBom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
    $start = if ($hasBom) { 3 } else { 0 }
    $raw = $encoding.GetString($bytes, $start, $bytes.Length - $start)
    $hasCRLF = $raw.Contains("`r`n")
    $lineSep = if ($hasCRLF) { "`r`n" } else { "`n" }
    $lines = $raw.Split([string[]]$lineSep, [StringSplitOptions]::None)
    $inDbSection = $false
    $changed = $false
    $newLines = @()
    foreach ($line in $lines) {
        $trimmed = $line.TrimStart()
        if ($trimmed.Length -gt 0 -and $trimmed[0] -eq '[' -and $trimmed.TrimEnd().EndsWith(']')) {
            $sectionName = $trimmed.Substring(1, $trimmed.Length - 2).Trim()
            $inDbSection = ($sectionName -eq 'veritabani')
        }
        if ($inDbSection -and $trimmed -match '^\s*port\s*=') {
            $parts = $line.Split('=', 2)
            $newLine = $parts[0] + '=6543'
            if ($newLine -ne $line) { $changed = $true }
            $newLines += $newLine
        } else {
            $newLines += $line
        }
    }
    if ($changed) {
        $newRaw = $newLines -join $lineSep
        $newBytes = $encoding.GetBytes($newRaw)
        if ($hasBom) {
            $finalBytes = New-Object byte[] ($newBytes.Length + 3)
            $finalBytes[0] = 0xEF; $finalBytes[1] = 0xBB; $finalBytes[2] = 0xBF
            [Array]::Copy($newBytes, 0, $finalBytes, 3, $newBytes.Length)
        } else {
            $finalBytes = $newBytes
        }
        [System.IO.File]::WriteAllBytes($_.FullName, $finalBytes)
        $results += @{ Dosya = $_.Name; Yolu = $_.FullName; Degisti = $true }
    } else {
        $results += @{ Dosya = $_.Name; Yolu = $_.FullName; Degisti = $false }
    }
}
$results | Format-Table -AutoSize

